package com.company.platform.aigateway.orchestration;import java.util.*;import org.springframework.stereotype.Component;@Component public class PolicyEngine{public void authorize(UUID tenantId,UUID requestedTenant,String classification,Set<String>permissions){if(tenantId==null||requestedTenant==null||!tenantId.equals(requestedTenant))throw new SecurityException("tenant isolation violation");if(classification==null||classification.isBlank())throw new SecurityException("classification required");if(permissions==null||permissions.isEmpty())throw new SecurityException("permission required");}}
